import { DESKTOP_COLS_NUMBER, MOBILE_COLS_NUMBER, TABLET_COLS_NUMBER } from "./constants";
import { updateGridPropToState } from "./updateGridPropToState";
import { updateGridStartPropToState } from "./updateGridStartPropToState";
import { setGridProp } from "./setGridProp";
export const updateGridStateFromProps = (gridState, item) => {
    const { gridLg, gridMd, gridSm, gridLgStart, gridMdStart, gridSmStart } = item.props;
    updateGridPropToState(gridState, item);
    updateGridStartPropToState(gridState, item);
    setGridProp(gridState, gridLg, "lg", DESKTOP_COLS_NUMBER);
    setGridProp(gridState, gridMd, "md", TABLET_COLS_NUMBER);
    setGridProp(gridState, gridSm, "sm", MOBILE_COLS_NUMBER);
    setGridProp(gridState, gridLgStart, "lgStart", DESKTOP_COLS_NUMBER);
    setGridProp(gridState, gridMdStart, "mdStart", TABLET_COLS_NUMBER);
    setGridProp(gridState, gridSmStart, "smStart", MOBILE_COLS_NUMBER);
};
